// Generate Claude Code config from the shared sources used by Codex.
// Sources of truth: AGENTS.md, .skills/<name>/, .reviewers/*.toml
// Generated (do not edit): .claude/skills/<name>/, .claude/agents/*.md
// Usage: node script/sync-claude.mjs
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

const root = resolve(import.meta.dirname, "..");
const skillsSrc = join(root, ".skills");
const reviewersSrc = join(root, ".reviewers");
const skillsOut = join(root, ".claude", "skills");
const agentsOut = join(root, ".claude", "agents");
const GENERATED = "<!-- Generated by script/sync-claude.mjs from the shared source. Do not edit. -->";

function syncSkills() {
  mkdirSync(skillsOut, { recursive: true });
  for (const name of readdirSync(skillsSrc)) {
    const src = join(skillsSrc, name);
    if (!statSync(src).isDirectory() || !existsSync(join(src, "SKILL.md"))) continue;
    const dest = join(skillsOut, name);
    rmSync(dest, { recursive: true, force: true });
    // Codex-only metadata (agents/openai.yaml) is not needed by Claude.
    cpSync(src, dest, { recursive: true });
    rmSync(join(dest, "agents"), { recursive: true, force: true });
    const file = join(dest, "SKILL.md");
    const text = readFileSync(file, "utf8")
      // .claude/skills/<name>/ is one level deeper than .skills/<name>/
      .replaceAll("](../../AGENTS.md)", "](../../../AGENTS.md)");
    writeFileSync(file, text);
    console.log(`skill  ${name}`);
  }
}

function tomlString(text, key) {
  const m = text.match(new RegExp(String.raw`^${key}\s*=\s*"((?:[^"\\]|\\.)*)"`, "m"));
  return m && JSON.parse(`"${m[1]}"`);
}

function tomlBlock(text, key) {
  const m = text.match(new RegExp(String.raw`^${key}\s*=\s*"""\n?([\s\S]*?)"""`, "m"));
  return m && m[1].trim();
}

function syncReviewers() {
  mkdirSync(agentsOut, { recursive: true });
  for (const file of readdirSync(reviewersSrc).filter((f) => f.endsWith(".toml"))) {
    const text = readFileSync(join(reviewersSrc, file), "utf8");
    const name = tomlString(text, "name")?.replaceAll("_", "-");
    const description = tomlString(text, "description");
    const body = tomlBlock(text, "developer_instructions");
    if (!name || !description || !body) throw new Error(`${file}: missing name, description, or developer_instructions`);
    const out = [
      "---",
      `name: ${name}`,
      `description: ${JSON.stringify(description)}`,
      "tools: Read, Grep, Glob, Bash",
      "---",
      GENERATED,
      "",
      body,
      "",
    ].join("\n");
    writeFileSync(join(agentsOut, `${name}.md`), out);
    console.log(`agent  ${name}`);
  }
}

syncSkills();
syncReviewers();
